INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q41','exam-fe','IDS','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問41・改編】IDSの機能はどれか。','[{"id":"a","text":"PCに導入済みのソフトが最新バージョンか確認する"},{"id":"b","text":"検査対象へテストデータを送り応答から脆弱性を検出する"},{"id":"c","text":"サーバやネットワークを監視し、侵入や侵害を検知したら管理者に通知する"},{"id":"d","text":"情報セキュリティ対策と企業情報を入力して組織の取組状況を自己診断する"}]','"c"','IDSは不審な侵入・侵害を監視して検知する仕組み。 中文：入侵检测系统监视服务器与网络，并报告检测到的入侵。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q57','exam-fe','サービスデスク','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問57・改編】ローカルサービスデスクの特徴はどれか。','[{"id":"a","text":"1拠点や少数拠点に集中して要員を効率配置し大量の問い合わせに対応する"},{"id":"b","text":"利用者の近くに配置し、言語や文化の違いに応じた対応や専門要員によるVIP対応を行う"},{"id":"c","text":"分散した要員が通信技術によって単一窓口のようにサービスを提供する"},{"id":"d","text":"分散拠点を含む全要員を中央で統括管理する"}]','"b"','ローカル型は利用者に近い拠点に窓口を置き、地域や個別の需要に対応する。 中文：本地服务台靠近用户，便于处理当地语言、文化和个别需求。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q71','exam-fe','セル生産','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問71・改編】セル生産方式の利点が生かせる対象はどれか。','[{"id":"a","text":"生産性を上げるため大量生産が必要なもの"},{"id":"b","text":"製品仕様が長期間変わらないもの"},{"id":"c","text":"多種類かつ柔軟な生産が求められるもの"},{"id":"d","text":"標準化・単純化・専門化による分業が必要なもの"}]','"c"','セル生産は少人数のチームでまとまった工程を担当し、多品種や需要変動に柔軟に対応しやすい。 中文：单元生产由小组完成一组工序，适合多品种和灵活生产。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q74','exam-fe','SEO','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問74・改編】SEOの説明はどれか。','[{"id":"a","text":"ECの購入履歴を分析して購入候補を自動推薦する"},{"id":"b","text":"Web広告をきっかけに商品が売れた場合、成功報酬を得る"},{"id":"c","text":"検索結果で自社サイトが上位に表示されるようページ内容などを改善する"},{"id":"d","text":"検索エンジンと契約し、関連キーワード検索時に広告を表示する"}]','"c"','SEOは検索エンジンの自然検索結果で見つけられやすくするための改善。成果報酬広告や検索連動広告とは区別する。 中文：SEO改善网页使其更易在自然搜索结果中被找到，与付费广告不同。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q78','exam-fe','定額法の減価償却','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問78・改編】建物の取得価額は10,000千円、前期までの減価償却累計額は3,000千円。定額法で耐用年数20年、残存価額0、会計期間1年とすると、当期の減価償却費は何千円か。','[{"id":"a","text":"150"},{"id":"b","text":"350"},{"id":"c","text":"500"},{"id":"d","text":"650"}]','"c"','定額法では(取得価額−残存価額)÷耐用年数=10,000÷20=500千円。累計額を再度差し引かない。 中文：直线法每年折旧额为10000÷20=500千日元，不再减去已有累计折旧。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
